// Kto je checker pre dané depo k danému dátumu — najprv sa pozrie, či nie je
// aktívna dočasná náhrada (napr. dovolenka checkera), inak vráti dedikovaného checkera.
function resolveCheckerId(depoCheckers, checkerSubstitutions, depo, dateISO) {
  // Ak sa prekrývajú dve náhrady pre to isté depo/dátum (napr. stará zabudnutá
  // a nová opravená), zoberie sa tá NAJNOVŠIE zadaná — platforma ich pridáva vždy
  // na koniec zoznamu, preto sa hľadá od konca, nie od začiatku.
  const list = checkerSubstitutions || [];
  for (let i = list.length - 1; i >= 0; i--) {
    const s = list[i];
    if (s.depo === depo && dateISO >= s.startDate && dateISO <= s.endDate) return s.substituteTechnicianId;
  }
  return depoCheckers?.[depo] || null;
}
// Prekrývajú sa dva dátumové rozsahy? Chýbajúci koniec (null) = bez konca (do nekonečna).
function rangesOverlap(aStart, aEnd, bStart, bEnd) {
  const aEndsAt = aEnd || "9999-12-31";
  const bEndsAt = bEnd || "9999-12-31";
  return aStart <= bEndsAt && bStart <= aEndsAt;
}
