/* ---------------------------------------------------------
   Výber spôsobu odoslania emailu — Outlook Web alebo mailto (desktop platforma/mobil)
--------------------------------------------------------- */
function MailChoiceModal({ mail, onClose }) {
  const [remember, setRemember] = useState(true);

  function choose(client) {
    if (remember) {
      try {
        localStorage.setItem(MAIL_PREF_KEY, client);
      } catch (e) {
        console.error("Nepodarilo sa uložiť preferenciu (localStorage nedostupný)", e);
      }
    }
    sendMailWithClient(client, mail);
    onClose();
  }

  return (
    <Modal title="Ako chcete odoslať email?" onClose={onClose}>
      <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 14 }}>
        <button className="btn btn-accent" style={{ padding: "12px 16px", textAlign: "left" }} onClick={() => choose("web")}>
          🌐 Outlook Web (otvorí v novej karte prehliadača)
        </button>
        <button className="btn btn-ghost" style={{ padding: "12px 16px", textAlign: "left" }} onClick={() => choose("desktop")}>
          💻 Outlook desktop / mobilná platforma
        </button>
      </div>
      <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, color: "var(--text-dim)" }}>
        <input type="checkbox" checked={remember} onChange={(e) => setRemember(e.target.checked)} />
        Zapamätať si túto voľbu (nabudúce sa už nepýtať)
      </label>
    </Modal>
  );
}


/* ---------------------------------------------------------
   User menu — jedno rozbaľovacie miesto pre všetky nastavenia
   (tmavý režim, mail, admin veci) namiesto radu tlačidiel v hlavičke
--------------------------------------------------------- */
function UserMenu({ currentUser, viewAsRole, onSetViewAsRole, darkMode, onToggleDarkMode, onOpenUserAdmin, onExportBackup, onImportBackup, canExport, canImport, onLogout }) {
  const [open, setOpen] = useState(false);
  const isAdmin = isAdminUser(currentUser);

  const itemStyle = {
    display: "block",
    width: "100%",
    textAlign: "left",
    background: "transparent",
    border: "none",
    padding: "8px 10px",
    fontSize: 13,
    color: "var(--text)",
    cursor: "pointer",
    borderRadius: 5,
  };
  const sectionLabel = { fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".05em", color: "var(--text-dim)", padding: "8px 10px 2px" };
  const divider = { height: 1, background: "var(--border)", margin: "4px 0" };

  return (
    <div style={{ position: "relative" }}>
      <button
        onClick={() => setOpen((v) => !v)}
        style={{
          fontSize: 11,
          color: "#fff",
          background: "rgba(255,255,255,.12)",
          border: "1px solid rgba(255,255,255,.25)",
          borderRadius: 4,
          padding: "3px 10px",
          cursor: "pointer",
        }}
      >
        {currentUser.name} · {roleLabel(currentUser.role)}
        {isAdmin && viewAsRole && <span style={{ color: "#ffe08a" }}> · zobrazujem ako: {roleLabel(viewAsRole)}</span>}
        <span style={{ marginLeft: 6 }}>▾</span>
      </button>
      {open && (
        <>
          <div style={{ position: "fixed", inset: 0, zIndex: 200 }} onClick={() => setOpen(false)} />
          <div
            className="panel dropdown-panel"
            style={{ position: "absolute", top: "calc(100% + 8px)", right: 0, width: 290, maxWidth: "90vw", zIndex: 201, padding: 6 }}
          >
            <button style={itemStyle} onClick={() => { onToggleDarkMode(); }} onMouseEnter={(e) => (e.currentTarget.style.background = "var(--panel-2)")} onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}>
              {darkMode ? "☀ Svetlý režim" : "🌙 Tmavý režim"}
            </button>
            <button
              style={itemStyle}
              onMouseEnter={(e) => (e.currentTarget.style.background = "var(--panel-2)")}
              onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
              onClick={() => {
                try {
                  localStorage.removeItem(MAIL_PREF_KEY);
                } catch (e) {}
                alert("Pri ďalšom odosielaní emailu sa platforma znova opýta, ako ho chcete otvoriť.");
                setOpen(false);
              }}
            >
              ✉️ Zmeniť spôsob mailu
            </button>

            {isAdmin && (
              <>
                <div style={divider} />
                <div style={sectionLabel}>Zobraziť platformu ako</div>
                <div style={{ padding: "2px 10px 8px" }}>
                  <select
                    value={viewAsRole || ""}
                    onChange={(e) => onSetViewAsRole(e.target.value || null)}
                    title="Dočasne si pozrieť platformu ako iná rola (nemení skutočnú rolu v databáze)"
                    style={{ width: "100%", fontSize: 12 }}
                  >
                    <option value="">Administrátor (skutočná rola)</option>
                    {ROLES.filter((r) => r.id !== "admin").map((r) => (
                      <option key={r.id} value={r.id}>{r.label}</option>
                    ))}
                  </select>
                </div>
                <div style={divider} />
                <div style={sectionLabel}>Administrácia</div>
                <button style={itemStyle} onMouseEnter={(e) => (e.currentTarget.style.background = "var(--panel-2)")} onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")} onClick={() => { onOpenUserAdmin(); setOpen(false); }}>
                  👤 Používatelia
                </button>
                {canExport && (
                  <button style={itemStyle} onMouseEnter={(e) => (e.currentTarget.style.background = "var(--panel-2)")} onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")} onClick={() => { onExportBackup(); setOpen(false); }}>
                    ⬇ Export dát
                  </button>
                )}
                {canImport && (
                  <label
                    style={{ ...itemStyle, display: "block" }}
                    onMouseEnter={(e) => (e.currentTarget.style.background = "var(--panel-2)")}
                    onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
                  >
                    ⬆ Import dát
                    <input
                      type="file"
                      accept="application/json,.json"
                      style={{ display: "none" }}
                      onChange={(e) => {
                        const file = e.target.files?.[0];
                        if (file) onImportBackup(file);
                        e.target.value = "";
                        setOpen(false);
                      }}
                    />
                  </label>
                )}
              </>
            )}

            <div style={divider} />
            <button
              style={{ ...itemStyle, color: "var(--danger)" }}
              onMouseEnter={(e) => (e.currentTarget.style.background = "var(--panel-2)")}
              onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
              onClick={onLogout}
            >
              Odhlásiť sa
            </button>
          </div>
        </>
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   Notification bell — skutočné upozornenia (nie len vizuálne odznaky)
--------------------------------------------------------- */
function NotificationBell({ notifications, unreadCount, currentUserId, onMarkRead, onMarkAllRead, onNavigate }) {
  const [open, setOpen] = useState(false);
  const sorted = [...(notifications || [])].sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1));

  function fmtWhen(iso) {
    try {
      const d = new Date(iso);
      return d.toLocaleDateString("sk-SK") + " " + d.toLocaleTimeString("sk-SK", { hour: "2-digit", minute: "2-digit" });
    } catch (e) {
      return "";
    }
  }

  return (
    <div style={{ position: "relative" }}>
      <button
        onClick={() => setOpen((v) => !v)}
        style={{
          fontSize: 13,
          color: "#fff",
          background: unreadCount > 0 ? "rgba(255,255,255,.2)" : "rgba(255,255,255,.12)",
          border: "1px solid rgba(255,255,255,.25)",
          borderRadius: 4,
          padding: "3px 9px",
          cursor: "pointer",
          position: "relative",
        }}
        title="Upozornenia"
      >
        🔔
        {unreadCount > 0 && (
          <span
            style={{
              position: "absolute",
              top: -5,
              right: -5,
              background: "var(--danger)",
              color: "#fff",
              borderRadius: 10,
              fontSize: 10,
              fontWeight: 700,
              minWidth: 16,
              height: 16,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              padding: "0 3px",
            }}
          >
            {unreadCount > 9 ? "9+" : unreadCount}
          </span>
        )}
      </button>
      {open && (
        <>
          <div style={{ position: "fixed", inset: 0, zIndex: 200 }} onClick={() => setOpen(false)} />
          <div
            className="panel dropdown-panel"
            style={{
              position: "absolute",
              top: "calc(100% + 8px)",
              right: 0,
              width: 360,
              maxWidth: "90vw",
              maxHeight: "70vh",
              overflowY: "auto",
              zIndex: 201,
              padding: 0,
            }}
          >
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px 14px", borderBottom: "1px solid var(--border)" }}>
              <span className="label-font" style={{ fontSize: 13, fontWeight: 700, color: "var(--text)" }}>Upozornenia</span>
              {unreadCount > 0 && (
                <button
                  className="btn btn-ghost"
                  style={{ fontSize: 11, padding: "3px 8px" }}
                  onClick={() => onMarkAllRead(sorted.map((n) => n.id))}
                >
                  Označiť všetky ako prečítané
                </button>
              )}
            </div>
            {sorted.length === 0 ? (
              <div style={{ padding: 24, textAlign: "center", color: "var(--text-dim)", fontSize: 13 }}>Zatiaľ žiadne upozornenia.</div>
            ) : (
              sorted.map((n) => {
                const isUnread = !n.readBy.includes(currentUserId);
                const clickable = isUnread || !!n.link;
                return (
                  <div
                    key={n.id}
                    onClick={() => {
                      if (isUnread) onMarkRead(n.id);
                      if (n.link) {
                        onNavigate?.(n.link);
                        setOpen(false);
                      }
                    }}
                    style={{
                      padding: "10px 14px",
                      borderBottom: "1px solid var(--border)",
                      background: isUnread ? "var(--accent-light)" : "transparent",
                      cursor: clickable ? "pointer" : "default",
                    }}
                  >
                    <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 3 }}>
                      {isUnread && <span style={{ width: 7, height: 7, borderRadius: "50%", background: "var(--accent)", flexShrink: 0 }} />}
                      <span style={{ fontSize: 12, fontWeight: 700 }}>{n.title}</span>
                      {n.link && <span style={{ marginLeft: "auto", fontSize: 10, color: "var(--accent)" }}>zobraziť →</span>}
                    </div>
                    <div style={{ fontSize: 12, color: "var(--text)", marginBottom: 3 }}>{n.message}</div>
                    <div style={{ fontSize: 10, color: "var(--text-dim)" }}>{fmtWhen(n.createdAt)}</div>
                  </div>
                );
              })
            )}
          </div>
        </>
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   "Dokumenty" — záložka s rozbaľovacím menu podzáložiek
   (zatiaľ pripravená prázdna, podzáložky sa doplnia neskôr)
--------------------------------------------------------- */
function DocumentsTabButton({ active, subTabs, onPick }) {
  const [open, setOpen] = useState(false);
  return (
    <div style={{ position: "relative" }}>
      <button
        onClick={() => setOpen((v) => !v)}
        className="label-font"
        style={{
          padding: "7px 12px",
          borderRadius: "6px 6px 0 0",
          fontSize: 13,
          letterSpacing: "0.04em",
          background: active ? "var(--accent-light)" : "transparent",
          color: active ? "var(--accent)" : "var(--text-dim)",
          border: "1px solid transparent",
          borderBottom: active ? "3px solid var(--accent)" : "3px solid transparent",
          marginBottom: -2,
          cursor: "pointer",
          whiteSpace: "nowrap",
          flexShrink: 0,
        }}
      >
        Dokumenty ▾
      </button>
      {open && (
        <>
          <div style={{ position: "fixed", inset: 0, zIndex: 200 }} onClick={() => setOpen(false)} />
          <div className="panel" style={{ position: "absolute", top: "calc(100% + 6px)", left: 0, minWidth: 220, zIndex: 201, padding: 6 }}>
            {subTabs.length === 0 ? (
              <div style={{ fontSize: 12, color: "var(--text-dim)", padding: "8px 10px" }}>
                Táto sekcia sa pripravuje.
              </div>
            ) : (
              subTabs.map((st) => (
                <button
                  key={st.id}
                  onClick={() => {
                    onPick(st);
                    setOpen(false);
                  }}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 6,
                    width: "100%",
                    textAlign: "left",
                    background: "transparent",
                    border: "none",
                    padding: "8px 10px",
                    fontSize: 13,
                    color: "var(--text)",
                    cursor: "pointer",
                    borderRadius: 5,
                  }}
                  onMouseEnter={(e) => (e.currentTarget.style.background = "var(--panel-2)")}
                  onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
                >
                  {st.label}
                  {st.url && <span style={{ marginLeft: "auto", fontSize: 11, color: "var(--text-dim)" }}>↗</span>}
                </button>
              ))
            )}
          </div>
        </>
      )}
    </div>
  );
}

