/* ---------------------------------------------------------
   Damage assign modal (assign a damage report to a technician/day)
--------------------------------------------------------- */
function DamageAssignModal({ damage, technicians, assignments, today, onClose, onSave, onBack }) {
  const [technicianIds, setTechnicianIds] = useState(damage.technicianIds || (damage.technicianId ? [damage.technicianId] : []));
  const [date, setDate] = useState(damage.assignedDate || today);
  const canSave = technicianIds.length > 0 && date;
  const hasExistingAssignment = (damage.technicianIds && damage.technicianIds.length > 0) || !!damage.technicianId;

  function toggle(id) {
    setTechnicianIds((prev) => (prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]));
  }

  // Vyťaženosť — koľko má technik na zvolený deň už priradených iných vecí.
  // Len informatívne, nič to neblokuje (technik môže mať aj viac servisov v deň).
  // Dovolenka/PN sa do tohto počtu nezarátava — na tie sa upozorňuje zvlášť,
  // jasne, nižšie (aby sa dispečer omylom nespoliehal na to, že technik je
  // k dispozícii len preto, že počet vyzeral nízky).
  const ABSENCE_LABELS = { dovolenka: "Na dovolenke", pn: "Na PN / u doktora" };
  function absenceOn(technicianId) {
    const a = (assignments || []).find((x) => x.technicianId === technicianId && x.date === date && (x.kind === "dovolenka" || x.kind === "pn"));
    return a ? ABSENCE_LABELS[a.kind] : null;
  }
  function workloadOn(technicianId) {
    return (assignments || []).filter(
      (a) => a.technicianId === technicianId && a.date === date && a.damageId !== damage.id && a.kind !== "dovolenka" && a.kind !== "pn"
    ).length;
  }

  return (
    <Modal title={`Prideliť · ${damage.code}`} onClose={onClose}>
      {onBack && (
        <button className="btn btn-ghost" style={{ marginBottom: 14 }} onClick={onBack}>
          ← Späť na kartu stroja
        </button>
      )}
      <Field label="Technici * (dá sa vybrať viac)">
        <div style={{ display: "flex", flexDirection: "column", gap: 4, maxHeight: 220, overflowY: "auto", border: "1px solid var(--border)", borderRadius: 6, padding: 8 }}>
          {technicians.filter((t) => !t.archived).map((t) => {
            const absence = absenceOn(t.id);
            const workload = workloadOn(t.id);
            return (
              <label key={t.id} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, cursor: "pointer" }}>
                <input type="checkbox" checked={technicianIds.includes(t.id)} onChange={() => toggle(t.id)} />
                {t.skratka ? `${t.skratka} — ${t.name}` : t.name}
                {absence ? (
                  <span style={{ fontSize: 11, color: "var(--danger)", fontWeight: 700 }}>
                    — ⚠ {absence} {fmtDate(date)}
                  </span>
                ) : (
                  workload > 0 && (
                    <span style={{ fontSize: 11, color: "var(--warn)", fontWeight: 600 }}>
                      — už má na {fmtDate(date)} {workload} {workload === 1 ? "úlohu" : workload < 5 ? "úlohy" : "úloh"}
                    </span>
                  )
                )}
              </label>
            );
          })}
        </div>
      </Field>
      <Field label="Deň *"><input type="date" value={date} onChange={(e) => setDate(e.target.value)} style={{ width: "100%" }} /></Field>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        <button className="btn btn-accent" disabled={!canSave} onClick={() => onSave(technicianIds, date)}>
          Uložiť pridelenie
        </button>
        {hasExistingAssignment && (
          <button
            className="btn btn-ghost"
            style={{ color: "var(--danger)" }}
            onClick={() => { onSave([], date); onClose(); }}
            title="Odoberie technika/technikov a zmaže záznam aj z Plánu servisu"
          >
            Zrušiť priradenie
          </button>
        )}
      </div>
    </Modal>
  );
}

/* ---------------------------------------------------------
   Complete revision modal (revízia vykonaná)
--------------------------------------------------------- */
function CompleteRevisionModal({ damage, today, onClose, onSave }) {
  const [date, setDate] = useState(today);
  const isMerged = damage.revizeType === "ZZ+EZ";
  const [doneZZ, setDoneZZ] = useState(true);
  const [doneEZ, setDoneEZ] = useState(true);
  const canSave = date && (!isMerged || doneZZ || doneEZ);
  return (
    <Modal title={`Revízia vykonaná · ${damage.code}`} onClose={onClose}>
      <div style={{ fontSize: 12, color: "var(--text-dim)", marginBottom: 10 }}>{damage.popis}</div>
      {isMerged && (
        <div style={{ display: "flex", flexDirection: "column", gap: 6, marginBottom: 14, border: "1px solid var(--border)", borderRadius: 6, padding: 10 }}>
          <div style={{ fontSize: 12, color: "var(--text-dim)" }}>Čo bolo reálne vykonané?</div>
          <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, cursor: "pointer" }}>
            <input type="checkbox" checked={doneZZ} onChange={(e) => setDoneZZ(e.target.checked)} />
            Revízia ZZ
          </label>
          <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, cursor: "pointer" }}>
            <input type="checkbox" checked={doneEZ} onChange={(e) => setDoneEZ(e.target.checked)} />
            Revízia EZ
          </label>
          {!doneZZ || !doneEZ ? (
            <div style={{ fontSize: 11, color: "var(--warn)" }}>
              {!doneZZ && !doneEZ
                ? "Zaškrtni aspoň jednu, inak nie je čo uložiť."
                : `Nezaškrtnutá časť (${!doneZZ ? "ZZ" : "EZ"}) ostane naďalej otvorená v Revíziách.`}
            </div>
          ) : null}
        </div>
      )}
      <Field label="Dátum vykonania revízie *">
        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} style={{ width: "100%" }} />
      </Field>
      <div style={{ fontSize: 12, color: "var(--text-dim)", marginBottom: 14 }}>
        Ďalšia revízia sa na karte stroja automaticky nastaví na {fmtDate(addDaysISO(date, 365))} (rok od vykonania).
      </div>
      <button className="btn btn-accent" disabled={!canSave} onClick={() => onSave(date, { zz: doneZZ, ez: doneEZ })}>
        Uložiť
      </button>
    </Modal>
  );
}

function CompleteUradnaSkuskaModal({ damage, today, onClose, onSave }) {
  const [date, setDate] = useState(today);
  const nextYear = date ? Number(date.slice(0, 4)) + 10 : null;
  return (
    <Modal title={`Úradná skúška vykonaná · ${damage.code}`} onClose={onClose}>
      <div style={{ fontSize: 12, color: "var(--text-dim)", marginBottom: 10 }}>{damage.popis}</div>
      <Field label="Dátum vykonania úradnej skúšky *">
        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} style={{ width: "100%" }} />
      </Field>
      <div style={{ fontSize: 12, color: "var(--text-dim)", marginBottom: 14 }}>
        Ďalšia úradná skúška sa na karte stroja automaticky nastaví na rok {nextYear} (+10 rokov, podľa legislatívy).
      </div>
      <button className="btn btn-accent" disabled={!date} onClick={() => onSave(date)}>
        Uložiť
      </button>
    </Modal>
  );
}

/* ---------------------------------------------------------
   Resolve damage modal (Označiť ako vyriešené — dátum opravy + komentár)
--------------------------------------------------------- */
function ResolveDamageModal({ damage, today, onClose, onSave }) {
  const options = [
    { id: "opravene", label: "Opravené" },
    { id: "dalsi_zasah", label: "Potrebný ďalší servisný zásah" },
    { id: "caka_diely", label: "Čaká na diely" },
    { id: "zavazna_porucha", label: "Závažná porucha" },
  ];
  const [stav, setStav] = useState(damage.stav || (damage.resolved ? "opravene" : options[0].id));
  const [date, setDate] = useState(damage.opravaDatum || today);
  const [comment, setComment] = useState(damage.opravaKomentar || "");
  const canSave = stav && date && comment.trim();
  return (
    <Modal title={`Upraviť stav zákazky · ${damage.code}`} onClose={onClose}>
      <div style={{ fontSize: 12, color: "var(--text-dim)", marginBottom: 10 }}>{damage.popis}</div>
      <Field label="Stav *">
        <select value={stav} onChange={(e) => setStav(e.target.value)} style={{ width: "100%" }}>
          {options.map((o) => <option key={o.id} value={o.id}>{o.label}</option>)}
        </select>
      </Field>
      <Field label="Dátum *">
        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} style={{ width: "100%" }} />
      </Field>
      <Field label="Čo sa zistilo / vykonalo *">
        <textarea value={comment} onChange={(e) => setComment(e.target.value)} rows={3} placeholder="Popis zásahu…" style={{ width: "100%" }} />
      </Field>
      <button className="btn btn-accent" disabled={!canSave} onClick={() => onSave(stav, date, comment.trim())}>
        Uložiť
      </button>
    </Modal>
  );
}

/* ---------------------------------------------------------
   Damage resolution modal (read-only view from machine card history)
--------------------------------------------------------- */
function DamageResolutionModal({ damage, technicianById, protocolLogs, onClose, onBack }) {
  const d = damage;
  const isSimple = d.type === "revizia" || d.type === "uradnaSkuska";
  const techIds = d.technicianIds && d.technicianIds.length ? d.technicianIds : (d.technicianId ? [d.technicianId] : []);
  const techNames = techIds.map((id) => technicianById?.[id]?.name).filter(Boolean).join(", ");

  if (!d.resolved) {
    // Nové / Pridelené — len na čítanie. Reálne pridelenie sa dá robiť
    // len zo záložky Poškodenia/Externé, kde sú práva nastavené správne.
    const stavLabel = techIds.length ? "Pridelené" : "Nové";
    return (
      <Modal title={`Servisný záznam · ${d.code}`} onClose={onClose}>
        {onBack && (
          <button className="btn btn-ghost" style={{ marginBottom: 14 }} onClick={onBack}>
            ← Späť na kartu stroja
          </button>
        )}
        <div className="resp-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", border: "1px solid var(--border)", borderRadius: 8, overflow: "hidden", marginBottom: 14 }}>
          <CardField label="Nahlásené" value={fmtDate(d.dateReported)} />
          <CardField label="Stav" value={stavLabel} danger={!techIds.length} />
          <CardField label="Pridelené komu" value={techNames || "— zatiaľ nikomu —"} />
          <CardField label="Na kedy" value={d.assignedDate ? fmtDate(d.assignedDate) : null} />
        </div>
        <div style={{ fontSize: 12, color: "var(--text-dim)", marginBottom: 4 }}>Popis</div>
        <div style={{ fontSize: 13 }}>{d.popis}</div>
      </Modal>
    );
  }

  const doneDate = d.opravaDatum || d.vykonanaDatum;
  return (
    <Modal title={`Servisný záznam · ${d.code}`} onClose={onClose}>
      {onBack && (
        <button className="btn btn-ghost" style={{ marginBottom: 14 }} onClick={onBack}>
          ← Späť na kartu stroja
        </button>
      )}
      <div className="resp-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", border: "1px solid var(--border)", borderRadius: 8, overflow: "hidden", marginBottom: 14 }}>
        <CardField label="Nahlásené" value={fmtDate(d.dateReported)} />
        <CardField label={isSimple ? "Dátum vykonania" : "Dátum opravy"} value={doneDate ? fmtDate(doneDate) : null} />
      </div>
      <div style={{ fontSize: 12, color: "var(--text-dim)", marginBottom: 4 }}>Pôvodný popis</div>
      <div style={{ fontSize: 13, marginBottom: 14 }}>{d.popis}</div>
      {!isSimple && (
        <>
          <div style={{ fontSize: 12, color: "var(--text-dim)", marginBottom: 4 }}>Čo sa opravilo</div>
          <div style={{ fontSize: 13 }}>{d.opravaKomentar || "— bez komentára —"}</div>
        </>
      )}
      {(protocolLogs || []).filter((p) => p.damageId === d.id).map((p) => (
        <div key={p.id} style={{ marginTop: 14 }}>
          <div style={{ fontSize: 12, color: "var(--text-dim)", marginBottom: 4 }}>
            Vypísaný protokol — {p.technicianName || "—"} ({fmtDate(p.createdAt)})
          </div>
          <a href={p.imageUrl} target="_blank" rel="noreferrer">
            <img src={p.imageUrl} alt="Protokol" style={{ maxWidth: "100%", border: "1px solid var(--border)", borderRadius: 6 }} />
          </a>
        </div>
      ))}
    </Modal>
  );
}

function AddTechnicianModal({ existing, onClose, onSave }) {
  const [name, setName] = useState(existing?.name || "");
  const [skratka, setSkratka] = useState(existing?.skratka || "");
  const [spz, setSpz] = useState(existing?.spz || "");
  const [depo, setDepo] = useState(existing?.depo || "");
  const [phone, setPhone] = useState(existing?.phone || "");
  const [email, setEmail] = useState(existing?.email || "");
  return (
    <Modal title={existing ? "Upraviť technika" : "Pridať technika"} onClose={onClose}>
      <Field label="Meno *"><input value={name} onChange={(e) => setName(e.target.value)} style={{ width: "100%" }} /></Field>
      <div className="resp-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
        <Field label="Skratka (ERP)"><input value={skratka} onChange={(e) => setSkratka(e.target.value.toUpperCase())} style={{ width: "100%" }} /></Field>
        <Field label="ŠPZ servisného auta"><input value={spz} onChange={(e) => setSpz(e.target.value.toUpperCase())} style={{ width: "100%" }} /></Field>
      </div>
      <Field label="Depo *">
        <select value={depo} onChange={(e) => setDepo(e.target.value)} style={{ width: "100%" }}>
          <option value="">— vybrať depo —</option>
          {DEPO_OPTIONS.map((d) => <option key={d} value={d}>{d}</option>)}
        </select>
      </Field>
      <Field label="Telefón"><input value={phone} onChange={(e) => setPhone(e.target.value)} style={{ width: "100%" }} /></Field>
      <Field label="Email"><input value={email} onChange={(e) => setEmail(e.target.value)} style={{ width: "100%" }} /></Field>
      <button
        className="btn btn-accent"
        disabled={!name.trim() || !depo.trim()}
        onClick={() => onSave({ name: name.trim(), skratka: skratka.trim(), spz: spz.trim(), depo: depo.trim(), phone: phone.trim(), email: email.trim() })}
      >
        {existing ? "Uložiť zmeny" : "Uložiť"}
      </button>
    </Modal>
  );
}

/* ---------------------------------------------------------
   Technicians overview (today + tomorrow, per technician)
--------------------------------------------------------- */
/* ---------------------------------------------------------
   Servis — Prehľad: štatistika + rýchly prehľad mesiaca
   (rovnaká logika ako Prehľad Požičovne — dlaždice, klik = presmerovanie)
--------------------------------------------------------- */
function ServisOverview({ damages, technicians, assignments, weeklyDuty, machineById, depoCheckers, checkerSubstitutions, today, onNavigate }) {
  const [depoFilter, setDepoFilter] = useState(null);
  const depoOptions = DEPO_OPTIONS;
  const damageDepo = (d) => (d.type === "externa" ? d.assignedDepo : (machineCurrentLocation(machineById[d.machineId]) || d.location)) || "";
  const damagesInDepo = depoFilter ? damages.filter((d) => damageDepo(d).toLowerCase() === depoFilter.toLowerCase()) : damages;
  const techniciansInDepo = depoFilter ? technicians.filter((t) => (t.depo || "").toLowerCase() === depoFilter.toLowerCase()) : technicians;

  const newDamages = damagesInDepo.filter((d) => d.type === "poskodenie" && !d.resolved && !d.technicianId);
  const assignedDamages = damagesInDepo.filter((d) => d.type === "poskodenie" && !d.resolved && d.technicianId);
  const newExterna = damagesInDepo.filter((d) => d.type === "externa" && !d.resolved);
  const revisionOverdue = damagesInDepo.filter((d) => d.type === "revizia" && !d.resolved && d.overdue);
  const revisionSoon = damagesInDepo.filter((d) => d.type === "revizia" && !d.resolved && !d.overdue);
  const uradneSkusky = damagesInDepo.filter((d) => d.type === "uradnaSkuska" && !d.resolved);

  const tiles = [
    { key: "new", label: "Nové poškodenia (nepridelené)", color: "var(--danger)", count: newDamages.length, view: "poskodenia" },
    { key: "assigned", label: "Pridelené poškodenia", color: "var(--info)", count: assignedDamages.length, view: "poskodenia" },
    { key: "externa", label: "Nové externé zákazky", color: "var(--danger)", count: newExterna.length, view: "externe" },
    { key: "revOverdue", label: "Revízia po termíne", color: "var(--danger)", count: revisionOverdue.length, view: "revizie" },
    { key: "revSoon", label: "Revízia do 30 dní", color: "var(--warn)", count: revisionSoon.length, view: "revizie" },
    { key: "skusky", label: "Úradné skúšky", color: "var(--warn)", count: uradneSkusky.length, view: "uradne_skusky" },
  ];

  const today0 = today;
  const monthStartISO = today0.slice(0, 7) + "-01";
  const lastDay = new Date(Number(today0.slice(0, 4)), Number(today0.slice(5, 7)), 0).getDate();
  const monthEndISO = today0.slice(0, 7) + "-" + String(lastDay).padStart(2, "0");
  const monthLabel = new Date(today0 + "T00:00:00").toLocaleDateString("sk-SK", { month: "long", year: "numeric" });

  const monthlySummary = techniciansInDepo
    .filter((t) => !t.archived)
    .map((t) => {
      const kindDates = { pohotovost: [], dovolenka: [], pn: [] };
      assignments.forEach((a) => {
        if (a.technicianId !== t.id || !a.kind || !(a.kind in kindDates)) return;
        if (a.date < monthStartISO || a.date > monthEndISO) return;
        kindDates[a.kind].push(a.date);
      });
      const dutyWeeks = (weeklyDuty || [])
        .filter((w) => w.technicianId === t.id && w.weekStart <= monthEndISO && w.weekEnd >= monthStartISO)
        .sort((a, b) => (a.weekStart < b.weekStart ? -1 : 1));
      return { technician: t, kindDates, dutyWeeks };
    })
    .filter((s) => s.dutyWeeks.length > 0 || Object.values(s.kindDates).some((arr) => arr.length > 0));

  return (
    <div>
      <div className="quick-filters" style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14, flexWrap: "wrap" }}>
        {depoOptions.map((d) => (
          <button
            key={d}
            className="btn"
            onClick={() => setDepoFilter(depoFilter === d ? null : d)}
            style={{
              padding: "5px 10px",
              fontSize: 11,
              background: depoFilter === d ? "var(--accent)" : "transparent",
              color: depoFilter === d ? "#fff" : "var(--text-dim)",
              border: "1px solid " + (depoFilter === d ? "var(--accent)" : "var(--border)"),
            }}
          >
            {d}
          </button>
        ))}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 10, marginBottom: 20 }}>
        {tiles.filter((t) => t.count > 0).map((t) => (
          <div
            key={t.key}
            className="panel"
            onClick={() => onNavigate(t.view)}
            style={{ padding: "12px 14px", borderLeft: `3px solid ${t.color}`, cursor: "pointer" }}
            title="Kliknutím prejdete na podrobný zoznam"
          >
            <div className="label-font" style={{ color: t.color, fontSize: 26, fontWeight: 700, lineHeight: 1 }}>{t.count}</div>
            <div style={{ fontSize: 12, color: "var(--text-dim)", marginTop: 4 }}>{t.label}</div>
          </div>
        ))}
      </div>

      <div className="resp-grid" style={{ display: "grid", gridTemplateColumns: monthlySummary.length > 0 ? "1fr 1fr" : "1fr", gap: 14 }}>
        <div>
          <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--text-dim)", marginBottom: 8 }}>
            Checkeri podľa depa — dnes ({fmtDate(today)})
          </div>
          <div className="panel" style={{ padding: 0, overflow: "hidden" }}>
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Depo</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Aktuálny checker</th>
                </tr>
              </thead>
              <tbody>
                {DEPO_OPTIONS.map((d) => {
                  const checkerId = resolveCheckerId(depoCheckers, checkerSubstitutions, d, today);
                  const checker = checkerId ? technicians.find((t) => t.id === checkerId) : null;
                  const isSubstitute = (checkerSubstitutions || []).some(
                    (s) => s.depo === d && today >= s.startDate && today <= s.endDate
                  );
                  return (
                    <tr key={d} style={{ borderTop: "1px solid var(--border)" }}>
                      <td style={{ padding: "8px 12px", fontSize: 13, fontWeight: 600 }}>{d}</td>
                      <td style={{ padding: "8px 12px", fontSize: 13 }}>
                        {checker ? checker.name : <span style={{ color: "var(--text-dim)" }}>— nepridelené —</span>}
                        {isSubstitute && checker && (
                          <span style={{ fontSize: 11, color: "var(--warn)", marginLeft: 8 }}>(náhrada za dovolenku)</span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
        {monthlySummary.length > 0 && (
          <div className="panel" style={{ padding: 14 }}>
            <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--text-dim)", marginBottom: 8 }}>
              Rýchly prehľad — {monthLabel}
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {monthlySummary.map((s) => (
                <div key={s.technician.id} style={{ fontSize: 13, display: "flex", flexWrap: "wrap", gap: 4 }}>
                  <span style={{ fontWeight: 600 }}>{s.technician.name}:</span>
                  {s.kindDates.pohotovost.length > 0 && (
                    <span><span style={{ color: "var(--danger)", fontWeight: 600 }}>Pohotovosť</span> {compressDates(s.kindDates.pohotovost)}</span>
                  )}
                  {s.kindDates.dovolenka.length > 0 && (
                    <span>{s.kindDates.pohotovost.length > 0 ? " · " : ""}<span style={{ color: "var(--ok)", fontWeight: 600 }}>Dovolenka</span> {compressDates(s.kindDates.dovolenka)}</span>
                  )}
                  {s.kindDates.pn.length > 0 && (
                    <span>{(s.kindDates.pohotovost.length > 0 || s.kindDates.dovolenka.length > 0) ? " · " : ""}<span style={{ color: "var(--warn)", fontWeight: 600 }}>PN / Doktor</span> {compressDates(s.kindDates.pn)}</span>
                  )}
                  {s.dutyWeeks.map((w) => (
                    <span key={w.id}>
                      {(s.kindDates.pohotovost.length > 0 || s.kindDates.dovolenka.length > 0 || s.kindDates.pn.length > 0) ? " · " : ""}
                      <span style={{ color: "#6b7280", fontWeight: 600 }}>☎ Služba</span> {fmtDate(w.weekStart)}–{fmtDate(w.weekEnd)}
                    </span>
                  ))}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function TechniciansOverview({ technicians, assignments, machines, damages, weeklyDuty, today, onOpenAssignment, technicianFilter, setTechnicianFilter, depoFilter, setDepoFilter }) {
  const machineById = useMemo(() => Object.fromEntries(machines.map((m) => [m.id, m])), [machines]);
  const damageById = useMemo(() => Object.fromEntries((damages || []).map((d) => [d.id, d])), [damages]);
  const depoOptions = DEPO_OPTIONS;
  const QUICK_KIND_LABELS = { pohotovost: "Pohotovosť", dovolenka: "Dovolenka", pn: "PN / Doktor" };

  function isOnDuty(technicianId, iso) {
    return (weeklyDuty || []).some((w) => w.technicianId === technicianId && iso >= w.weekStart && iso <= w.weekEnd);
  }

  function daysForTechnician(t) {
    const list = [];
    let d = today;
    let guard = 0;
    while (list.length < 5 && guard < 60) {
      guard++;
      const dow = new Date(d + "T00:00:00").getDay();
      const isWeekend = dow === 0 || dow === 6;
      if (!isWeekend) {
        list.push(d);
      } else {
        const hasContent = assignments.some((a) => a.technicianId === t.id && a.date === d) || isOnDuty(t.id, d);
        if (hasContent) list.push(d);
      }
      d = addDaysISO(d, 1);
    }
    return list;
  }

  if (technicians.length === 0) {
    return (
      <div className="panel" style={{ padding: 30, textAlign: "center", color: "var(--text-dim)" }}>
        Zatiaľ nie sú pridaní žiadni technici. Pridajte ich v záložke „Technici“.
      </div>
    );
  }

  function jobLine(a) {
    const machine = a.machineId ? machineById[a.machineId] : null;
    const linkedDamage = a.damageId ? damageById[a.damageId] : null;
    const label = a.kind === "udalost" ? (a.poznamka || a.stroj || "Udalosť") : a.kind ? QUICK_KIND_LABELS[a.kind] || a.kind : (machine?.code || a.stroj || "— stroj neurčený —");
    const clickable = !a.kind;
    return (
      <div
        key={a.id}
        onClick={clickable ? () => onOpenAssignment(a, machine, linkedDamage) : undefined}
        style={{
          fontSize: 12,
          marginBottom: 4,
          paddingLeft: 8,
          borderLeft: `2px solid ${a.kind ? "var(--warn)" : linkedDamage ? damageColor(linkedDamage) : "var(--border)"}`,
          cursor: clickable ? "pointer" : "default",
        }}
      >
        <span style={{ fontWeight: 600, color: clickable ? "var(--accent)" : "inherit" }}>{label}</span>
        {!a.kind && (
          <span style={{ color: "var(--text-dim)" }}>{assignmentLocation(a, machineById) ? " · " + assignmentLocation(a, machineById) : ""}{a.firma ? " · " + a.firma : ""}</span>
        )}
        {a.poznamka && !a.kind && <div style={{ color: "var(--text-dim)" }}>{a.poznamka}</div>}
      </div>
    );
  }

  let visibleTechnicians = technicians.filter((t) => !t.archived);
  if (technicianFilter) visibleTechnicians = visibleTechnicians.filter((t) => t.id === technicianFilter);
  if (depoFilter) visibleTechnicians = visibleTechnicians.filter((t) => (t.depo || "").toLowerCase() === depoFilter.toLowerCase());

  return (
    <div>
      <div style={{ display: "flex", gap: 6, marginBottom: 14, flexWrap: "wrap" }}>
        {depoOptions.map((d) => (
          <button
            key={d}
            className="btn"
            onClick={() => setDepoFilter(depoFilter === d ? null : d)}
            style={{
              padding: "5px 10px",
              fontSize: 11,
              background: depoFilter === d ? "var(--accent)" : "transparent",
              color: depoFilter === d ? "#fff" : "var(--text-dim)",
              border: "1px solid " + (depoFilter === d ? "var(--accent)" : "var(--border)"),
            }}
          >
            {d}
          </button>
        ))}
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {visibleTechnicians.length === 0 && (
          <div className="panel" style={{ padding: 30, textAlign: "center", color: "var(--text-dim)" }}>
            Žiadny technik nezodpovedá filtru.
          </div>
        )}
        {visibleTechnicians.map((t) => {
          const techDays = daysForTechnician(t);
          return (
          <div key={t.id} className="panel" style={{ overflow: "hidden" }}>
            <div style={{ background: "#1a1a1a", color: "#fff", padding: "8px 14px", display: "flex", alignItems: "center", gap: 10 }}>
              <span className="label-font" style={{ fontSize: 13, fontWeight: 700, letterSpacing: ".04em", textTransform: "uppercase" }}>
                {t.skratka ? `${t.skratka} · ${t.name}` : t.name}
              </span>
              {(t.depo || t.spz) && (
                <span style={{ marginLeft: "auto", fontSize: 11, color: "rgba(255,255,255,.7)" }}>
                  {[t.depo, t.spz].filter(Boolean).join(" · ")}
                </span>
              )}
            </div>
            <div style={{ display: "grid", gridTemplateColumns: `repeat(${techDays.length}, 1fr)`, overflowX: "auto" }}>
              {techDays.map((iso, i) => {
                const dayAssignments = assignments.filter((a) => a.technicianId === t.id && a.date === iso);
                const onDuty = isOnDuty(t.id, iso);
                const dow = new Date(iso + "T00:00:00").getDay();
                return (
                  <div key={iso} style={{ padding: 12, borderRight: i < techDays.length - 1 ? "1px solid var(--border)" : "none", minWidth: 130 }}>
                    <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--text-dim)", marginBottom: 6 }}>
                      {DOW_NAMES_FULL[dow]} — {fmtDate(iso)}
                    </div>
                    {dayAssignments.length === 0 ? (
                      <div style={{ fontSize: 12, color: "var(--text-dim)" }}>Bez zákazky</div>
                    ) : (
                      dayAssignments.map(jobLine)
                    )}
                    {onDuty && (
                      <div style={{ fontSize: 11, color: "#6b7280", marginTop: 6, display: "flex", alignItems: "center", gap: 4 }}>
                        <span>☎</span> Služba na telefóne
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
          );
        })}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   Technician card modal (karta technika)
--------------------------------------------------------- */
function TechnicianCardModal({ technician, assignments, machines, today, user, onClose, onEdit, onArchive, onUnarchive }) {
  const t = technician;
  const machineById = useMemo(() => Object.fromEntries(machines.map((m) => [m.id, m])), [machines]);
  const upcoming = assignments
    .filter((a) => a.technicianId === t.id && a.date >= today)
    .sort((a, b) => (a.date < b.date ? -1 : 1))
    .slice(0, 8);

  return (
    <Modal title={`${t.name}${t.archived ? " (archivovaný)" : ""}`} onClose={onClose} wide>
      <div className="resp-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", border: "1px solid var(--border)", borderRadius: 8, overflow: "hidden", marginBottom: 14 }}>
        <CardField label="Skratka (ERP)" value={t.skratka} />
        <CardField label="ŠPZ servisného auta" value={t.spz} />
        <CardField label="Depo" value={t.depo} />
        <CardField label="Telefón" value={t.phone} />
        <CardField label="Email" value={t.email} />
      </div>
      <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--text-dim)", marginBottom: 6 }}>
        Nadchádzajúce zákazky
      </div>
      {upcoming.length === 0 ? (
        <div style={{ fontSize: 13, color: "var(--text-dim)", marginBottom: 14 }}>Zatiaľ nič naplánované.</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 6, marginBottom: 14 }}>
          {upcoming.map((a) => {
            const machine = a.machineId ? machineById[a.machineId] : null;
            return (
              <div key={a.id} style={{ fontSize: 12, paddingLeft: 8, borderLeft: "2px solid var(--border)" }}>
                <span className="mono" style={{ fontWeight: 600 }}>{fmtDate(a.date)}</span>
                {" · "}
                <span style={{ fontWeight: 600 }}>{machine?.code || a.stroj || "— stroj neurčený —"}</span>
                <span style={{ color: "var(--text-dim)" }}>{(machineCurrentLocation(machine) || a.umiestnenie) ? " · " + (machineCurrentLocation(machine) || a.umiestnenie) : ""}{a.firma ? " · " + a.firma : ""}</span>
              </div>
            );
          })}
        </div>
      )}
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        {can(user, "technician_edit") && <button className="btn btn-ghost" onClick={onEdit}>Upraviť</button>}
        {can(user, "technician_archive") && (
          <button className="btn btn-ghost" onClick={() => (t.archived ? onUnarchive() : onArchive())}>
            {t.archived ? "Vrátiť z archívu" : "Archivovať"}
          </button>
        )}
      </div>
    </Modal>
  );
}

/* ---------------------------------------------------------
   Technician service planner (Gantt, click day → assign)
--------------------------------------------------------- */
function TechnicianPlanner({ technicians, assignments, machines, damages, weeklyDuty, today, user, onCellClick, onQuickAssign, onQuickEventNote, onQuickWeeklyDuty, onQuickVacationWithSubstitute, onAddTechnician, onOpenTechnician, technicianFilter, setTechnicianFilter, depoFilter, setDepoFilter, depoCheckers, showArchived, setShowArchived }) {
  const [monthOffset, setMonthOffset] = useState(0);
  const [quickMode, setQuickMode] = useState(null); // null | 'udalost' | 'pohotovost' | 'dovolenka' | 'pn' | 'sluzba'
  const [pendingEventCell, setPendingEventCell] = useState(null); // { technicianId, date } — čaká na text poznámky pri "Udalosť"
  const [pendingVacationCell, setPendingVacationCell] = useState(null); // { technician, date, depos } — technik-checker ide na dovolenku, treba náhradu
  const QUICK_KINDS = [
    { id: "udalost", label: "Udalosť", color: "#0EA5E9", freeText: true },
    { id: "pohotovost", label: "Pohotovosť", color: "var(--danger)" },
    { id: "dovolenka", label: "Dovolenka", color: "var(--ok)" },
    { id: "pn", label: "PN / Doktor", color: "var(--warn)" },
    { id: "sluzba", label: "Služba na telefóne", color: "#6b7280", weekly: true },
  ];
  function isOnDuty(technicianId, iso) {
    return (weeklyDuty || []).some((w) => w.technicianId === technicianId && iso >= w.weekStart && iso <= w.weekEnd);
  }
  const depoOptions = DEPO_OPTIONS;
  let visibleTechnicians = showArchived ? technicians : technicians.filter((t) => !t.archived);
  if (technicianFilter) {
    visibleTechnicians = visibleTechnicians.filter((t) => t.id === technicianFilter);
  }
  if (depoFilter) {
    visibleTechnicians = visibleTechnicians.filter((t) => (t.depo || "").toLowerCase() === depoFilter.toLowerCase());
  }
  const base = new Date(today + "T00:00:00");
  const viewDate = new Date(base.getFullYear(), base.getMonth() + monthOffset, 1);
  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const monthLabel = viewDate.toLocaleDateString("sk-SK", { month: "long", year: "numeric" });

  const [monthWindow, setMonthWindow] = useState({ start: -1, end: 1 });
  useEffect(() => {
    setMonthWindow({ start: -1, end: 1 });
  }, [monthOffset]);

  // Nekonečné vodorovné rolovanie — okolo aktuálneho mesiaca sa vykreslí len
  // malý pás dní; keď sa priblížiš k okraju, potichu sa pridá ďalší mesiac
  // na daný koniec (viď handleCalendarScroll nižšie). Posuvník sa tým
  // prirodzene zmenšuje, tak ako pri bežnom nekonečnom scrollovaní.
  const allDays = useMemo(() => {
    const days = [];
    for (let mOff = monthWindow.start; mOff <= monthWindow.end; mOff++) {
      const d = new Date(year, month + mOff, 1);
      const y = d.getFullYear();
      const mo = d.getMonth();
      const count = new Date(y, mo + 1, 0).getDate();
      for (let day = 1; day <= count; day++) {
        days.push(`${y}-${String(mo + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`);
      }
    }
    return days;
  }, [year, month, monthWindow]);

  const machineById = useMemo(() => Object.fromEntries(machines.map((m) => [m.id, m])), [machines]);
  const damageById = useMemo(() => Object.fromEntries((damages || []).map((d) => [d.id, d])), [damages]);
  const byTechDate = useMemo(() => {
    const map = {};
    assignments.forEach((a) => {
      const key = `${a.technicianId}_${a.date}`;
      (map[key] = map[key] || []).push(a);
    });
    return map;
  }, [assignments]);

  const todayCellRef = useRef(null);
  const scrollContainerRef = useRef(null);
  const [displayedMonthLabel, setDisplayedMonthLabel] = useState(monthLabel);
  const prependAnchorRef = useRef(null); // { iso, left } zachytené tesne pred pridaním mesiaca dozadu

  useEffect(() => {
    setDisplayedMonthLabel(monthLabel);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [monthOffset]);

  // Po pridaní mesiaca na začiatok (dozadu) sa obsah predĺži smerom doľava —
  // bez tejto kompenzácie by to trhlo pohľad. Namiesto odhadu podľa celkovej
  // šírky (tá sa nedá spoľahnúť, lebo stĺpce sa mierne prepočítajú, keď ich
  // pribudne) sa zakotví na konkrétny deň — po prekreslení sa dohľadá presne
  // ten istý deň a scrollLeft sa doladí tak, aby ostal na tom istom mieste.
  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    const anchor = prependAnchorRef.current;
    if (!container || !anchor) return;
    const cell = container.querySelector(`[data-day-iso="${anchor.iso}"]`);
    if (cell) {
      const newLeft = cell.getBoundingClientRect().left;
      container.scrollLeft += newLeft - anchor.left;
    }
    prependAnchorRef.current = null;
  }, [allDays]);

  // Nadpis hore ("August 2026") sa pri vodorovnom rolovaní priebežne
  // aktualizuje podľa toho, ktorý deň je práve uprostred viditeľnej oblasti —
  // nech vždy ukazuje mesiac, na ktorom si sa reálne pozeráš. Zároveň, keď sa
  // priblížiš k jednému z okrajov, potichu sa pridá ďalší mesiac na ten
  // koniec — nekonečné rolovanie, kým nestlačíš "Dnes".
  function handleCalendarScroll() {
    const container = scrollContainerRef.current;
    if (!container || allDays.length === 0) return;
    const containerRect = container.getBoundingClientRect();
    const centerX = containerRect.left + containerRect.width / 2;
    const headerCells = container.querySelectorAll("[data-day-iso]");
    let closestIso = null;
    let closestDist = Infinity;
    let leftmostIso = null;
    let leftmostLeft = Infinity;
    headerCells.forEach((cell) => {
      const rect = cell.getBoundingClientRect();
      const dist = Math.abs(rect.left + rect.width / 2 - centerX);
      if (dist < closestDist) {
        closestDist = dist;
        closestIso = cell.getAttribute("data-day-iso");
      }
      if (rect.right >= containerRect.left && rect.left < leftmostLeft) {
        leftmostLeft = rect.left;
        leftmostIso = cell.getAttribute("data-day-iso");
      }
    });
    if (closestIso) {
      const label = new Date(closestIso + "T00:00:00").toLocaleDateString("sk-SK", { month: "long", year: "numeric" });
      setDisplayedMonthLabel(label);
    }

    const EDGE_PX = 600;
    if (container.scrollLeft < EDGE_PX && !prependAnchorRef.current) {
      if (leftmostIso) prependAnchorRef.current = { iso: leftmostIso, left: leftmostLeft };
      setMonthWindow((w) => ({ ...w, start: w.start - 1 }));
    } else if (container.scrollLeft > container.scrollWidth - container.clientWidth - EDGE_PX) {
      setMonthWindow((w) => ({ ...w, end: w.end + 1 }));
    }
  }

  function scrollToToday() {
    try {
      const container = scrollContainerRef.current;
      const cell = todayCellRef.current;
      if (!container || !cell) return;
      const containerRect = container.getBoundingClientRect();
      const cellRect = cell.getBoundingClientRect();
      const delta = (cellRect.left + cellRect.width / 2) - (containerRect.left + containerRect.width / 2);
      container.scrollLeft = container.scrollLeft + delta;
    } catch (e) {
      // ignore — purely a convenience scroll
    }
  }

  // "Dnes" musí fungovať aj keď sa odscrolluje ďaleko bez toho, aby sa
  // klikli šípky (monthOffset teda ostáva 0) — preto tu explicitne
  // zresetujeme okno dní aj pozíciu scrollu, namiesto spoliehania sa na
  // efekt viazaný len na zmenu monthOffset.
  function goToToday() {
    setMonthWindow({ start: -1, end: 1 });
    setDisplayedMonthLabel(monthLabel);
    if (monthOffset !== 0) {
      setMonthOffset(0);
    } else {
      const t = setTimeout(scrollToToday, 50);
      return () => clearTimeout(t);
    }
  }

  useEffect(() => {
    if (monthOffset !== 0) return;
    const t = setTimeout(scrollToToday, 50);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [monthOffset]);

  if (technicians.length === 0) {
    return (
      <div className="panel" style={{ padding: 30, textAlign: "center", color: "var(--text-dim)" }}>
        Zatiaľ nie sú pridaní žiadni technici.
        <div style={{ marginTop: 12, fontSize: 12 }}>Pridáte ich v module Administratíva.</div>
      </div>
    );
  }

  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr auto 1fr", alignItems: "center", marginBottom: 14, gap: 10 }}>
        {can(user, "plan_quick_events") ? (
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center" }}>
            <span style={{ fontSize: 11, color: "var(--text-dim)" }}>Rýchle udalosti:</span>
            {QUICK_KINDS.map((k) => (
              <button
                key={k.id}
                className="btn"
                onClick={() => setQuickMode(quickMode === k.id ? null : k.id)}
                style={{
                  padding: "5px 10px",
                  fontSize: 11,
                  background: quickMode === k.id ? k.color : "transparent",
                  color: quickMode === k.id ? "#fff" : k.color,
                  border: "1px solid " + k.color,
                }}
              >
                {k.label}
              </button>
            ))}
            {quickMode && (
              <span style={{ fontSize: 11, color: "var(--text-dim)" }}>
                — kliknite na bunky technikov, kam chcete "{QUICK_KINDS.find((k) => k.id === quickMode)?.label}" pridať
              </span>
            )}
          </div>
        ) : <div />}
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <button className="btn btn-ghost" style={{ padding: "5px 10px" }} onClick={() => setMonthOffset((o) => o - 1)}>←</button>
          <span className="label-font" style={{ fontSize: 15, minWidth: 160, textAlign: "center", textTransform: "capitalize" }}>{displayedMonthLabel}</span>
          <button className="btn btn-ghost" style={{ padding: "5px 10px" }} onClick={() => setMonthOffset((o) => o + 1)}>→</button>
          {(monthOffset !== 0 || displayedMonthLabel !== monthLabel) && (
            <button className="btn btn-ghost" style={{ padding: "5px 10px", fontSize: 11 }} onClick={goToToday}>Dnes</button>
          )}
        </div>
        <div />
      </div>
      <div style={{ display: "flex", gap: 6, marginBottom: 14, flexWrap: "wrap" }}>
        {depoOptions.map((d) => (
          <button
            key={d}
            className="btn"
            onClick={() => setDepoFilter(depoFilter === d ? null : d)}
            style={{
              padding: "5px 10px",
              fontSize: 11,
              background: depoFilter === d ? "var(--accent)" : "transparent",
              color: depoFilter === d ? "#fff" : "var(--text-dim)",
              border: "1px solid " + (depoFilter === d ? "var(--accent)" : "var(--border)"),
            }}
          >
            {d}
          </button>
        ))}
      </div>
      <div className="panel" style={{ padding: 16 }}>
        <div ref={scrollContainerRef} onScroll={handleCalendarScroll} style={{ overflow: "auto", maxHeight: "65vh" }}>
          <div style={{ width: "100%", minWidth: "max-content" }}>
            <div
              style={{
                display: "grid",
                gridTemplateColumns: `var(--gantt-name-col) repeat(${allDays.length}, minmax(var(--gantt-plan-day-col), 1fr))`,
                gap: 2,
                position: "sticky",
                top: 0,
                zIndex: 4,
                background: "var(--panel)",
              }}
            >
              <div style={{ position: "sticky", left: 0, zIndex: 5, background: "var(--panel)" }}></div>
              {allDays.map((iso) => {
                const d = Number(iso.slice(8, 10));
                const isToday = iso === today;
                const dow = new Date(iso + "T00:00:00").getDay();
                const isWeekend = dow === 0 || dow === 6;
                return (
                  <div
                    key={iso}
                    ref={isToday ? todayCellRef : null}
                    data-day-iso={iso}
                    className="mono gantt-header-cell"
                    title={iso}
                    style={{
                      textAlign: "center",
                      fontSize: 11,
                      color: isToday ? "var(--accent)" : isWeekend ? "var(--warn)" : "var(--text-dim)",
                      fontWeight: isToday ? 700 : 400,
                      whiteSpace: "nowrap",
                      borderRight: "1px solid var(--border)",
                      paddingBottom: 4,
                      background: isWeekend ? "var(--warn-bg)" : "var(--panel)",
                    }}
                  >
                    <div style={{ fontSize: 9, textTransform: "uppercase", letterSpacing: ".03em" }}>{DOW_NAMES[dow]}</div>
                    <div>{d}</div>
                  </div>
                );
              })}
            </div>

            {visibleTechnicians.map((t) => (
              <div
                key={t.id}
                style={{
                  display: "grid",
                  gridTemplateColumns: `var(--gantt-name-col) repeat(${allDays.length}, minmax(var(--gantt-plan-day-col), 1fr))`,
                  gap: 2,
                  marginBottom: 3,
                  paddingBottom: 3,
                  borderBottom: "1px solid var(--gantt-cell-border)",
                }}
              >
                <div
                  onClick={() => onOpenTechnician(t)}
                  style={{
                    lineHeight: 1.3,
                    whiteSpace: "nowrap",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                    cursor: "pointer",
                    position: "sticky",
                    left: 0,
                    zIndex: 2,
                    background: "var(--panel)",
                    paddingRight: 6,
                    paddingTop: 4,
                  }}
                  title="Zobraziť kartu technika"
                >
                  <div style={{ fontSize: 12, fontWeight: 600, color: "var(--accent)", overflow: "hidden", textOverflow: "ellipsis" }}>
                    {t.name}
                  </div>
                  {t.depo && (
                    <div style={{ fontSize: 10, color: "var(--text-dim)", overflow: "hidden", textOverflow: "ellipsis" }}>
                      {t.depo}
                    </div>
                  )}
                </div>
                {allDays.map((iso) => {
                  const dow = new Date(iso + "T00:00:00").getDay();
                  const isWeekend = dow === 0 || dow === 6;
                  const dayAssignments = byTechDate[`${t.id}_${iso}`] || [];
                  const dutyRecord = (weeklyDuty || []).find((w) => w.technicianId === t.id && iso >= w.weekStart && iso <= w.weekEnd);
                  const onDuty = !!dutyRecord;
                  const isDutyStart = onDuty && iso === dutyRecord.weekStart;
                  const canEditPlan = can(user, "plan_assign");
                  const canQuickEvents = can(user, "plan_quick_events");
                  const hasContent = dayAssignments.length > 0;
                  const handleClick = () => {
                    if (quickMode === "udalost" && canQuickEvents) return setPendingEventCell({ technicianId: t.id, date: iso });
                    if (quickMode === "sluzba" && canQuickEvents) return onQuickWeeklyDuty(t.id, iso);
                    if (quickMode === "dovolenka" && canQuickEvents) {
                      const depos = Object.entries(depoCheckers || {})
                        .filter(([, techId]) => techId === t.id)
                        .map(([depo]) => depo);
                      if (depos.length > 0) {
                        return setPendingVacationCell({ technician: t, date: iso, depos });
                      }
                      return onQuickAssign(t.id, iso, quickMode);
                    }
                    if (quickMode && canQuickEvents) return onQuickAssign(t.id, iso, quickMode);
                    if (!quickMode && (canEditPlan || hasContent)) return onCellClick(t.id, iso);
                  };
                  const cellClickable = quickMode ? canQuickEvents : (canEditPlan || hasContent);
                  const clickTitle = !cellClickable
                    ? "Nemáte oprávnenie upravovať plán servisu"
                    : quickMode === "sluzba"
                      ? "Nastaviť/zrušiť službu na telefóne pre celý týždeň"
                      : quickMode
                      ? `Pridať "${QUICK_KINDS.find((k) => k.id === quickMode)?.label}"`
                      : canEditPlan
                      ? "Kliknite pre pridelenie"
                      : "Kliknite pre zobrazenie";
                  return (
                    <div key={iso} style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                      {dayAssignments.length === 0 ? (
                        <div
                          onClick={handleClick}
                          title={clickTitle}
                          style={{
                            height: 26,
                            borderRadius: 4,
                            background: isWeekend ? "var(--warn-bg)" : "var(--gantt-cell-bg)",
                            border: "1px solid var(--gantt-cell-border)",
                            cursor: cellClickable ? "pointer" : "default",
                          }}
                        />
                      ) : (
                        dayAssignments.map((a) => {
                          const machine = a.machineId ? machineById[a.machineId] : null;
                          const linkedDamage = a.damageId ? damageById[a.damageId] : null;
                          const quickKind = a.kind ? QUICK_KINDS.find((k) => k.id === a.kind) : null;
                          const bg = quickKind ? quickKind.color : linkedDamage ? damageColor(linkedDamage) : "var(--info)";
                          const label = a.kind === "udalost" ? (a.poznamka || a.stroj || "Udalosť") : quickKind ? quickKind.label : (machine?.code || a.stroj || a.firma || "•");
                          const tooltip = a.kind === "udalost"
                            ? (a.poznamka || "Udalosť")
                            : quickKind
                            ? quickKind.label
                            : `${machine?.code || a.stroj || "—"} · ${machineCurrentLocation(machine) || a.umiestnenie || "—"} · ${a.firma || "—"}${linkedDamage ? " · " + damageLabel(linkedDamage) : ""}`;
                          return (
                            <div
                              key={a.id}
                              onClick={handleClick}
                              title={tooltip}
                              style={{
                                height: 22,
                                borderRadius: 4,
                                background: bg,
                                color: "#fff",
                                fontSize: 9,
                                fontWeight: 600,
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                whiteSpace: "nowrap",
                                overflow: "hidden",
                                textOverflow: "ellipsis",
                                cursor: "pointer",
                                padding: "0 4px",
                              }}
                              className="gantt-cell"
                            >
                              {label}
                            </div>
                          );
                        })
                      )}
                      {onDuty && (
                        <div
                          onClick={handleClick}
                          title="Služba na telefóne (celý týždeň)"
                          style={{
                            height: 11,
                            borderRadius: 3,
                            background: "#6b7280",
                            opacity: 0.85,
                            cursor: "pointer",
                            display: "flex",
                            alignItems: "center",
                            justifyContent: isDutyStart ? "flex-start" : "center",
                            paddingLeft: isDutyStart ? 3 : 0,
                            fontSize: 8,
                            lineHeight: 1,
                            color: "#fff",
                          }}
                        >
                          {isDutyStart ? "☎" : ""}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            ))}
          </div>
        </div>
      </div>
      {pendingEventCell && (
        <QuickEventNoteModal
          onClose={() => setPendingEventCell(null)}
          onSave={(text) => {
            onQuickEventNote(pendingEventCell.technicianId, pendingEventCell.date, text);
            setPendingEventCell(null);
          }}
        />
      )}
      {pendingVacationCell && (
        <CheckerVacationModal
          technician={pendingVacationCell.technician}
          depos={pendingVacationCell.depos}
          clickedDate={pendingVacationCell.date}
          technicians={technicians}
          onClose={() => setPendingVacationCell(null)}
          onSave={({ startDate, endDate, substituteId }) => {
            onQuickVacationWithSubstitute(pendingVacationCell.technician.id, startDate, endDate, substituteId, pendingVacationCell.depos);
            setPendingVacationCell(null);
          }}
        />
      )}
    </div>
  );
}

