// Excel-štýl filter — zoznam hodnôt so zaškrtávacími políčkami, predvolene
// všetko zaškrtnuté (nič sa neschová, kým si niekto sám nezúži výber).
function ColumnFilterButton({ label, options, selected, onChange }) {
  const [open, setOpen] = useState(false);
  const allSelected = options.every((o) => selected.has(o));
  return (
    <span style={{ position: "relative", display: "inline-block", marginLeft: 4 }}>
      <button
        className="btn btn-ghost"
        style={{ padding: "1px 5px", fontSize: 10, opacity: allSelected ? 0.5 : 1 }}
        onClick={(e) => { e.stopPropagation(); setOpen((v) => !v); }}
        title={`Filter: ${label}`}
      >
        ▾
      </button>
      {open && (
        <div
          style={{
            position: "absolute", top: "100%", left: 0, marginTop: 2, zIndex: 30,
            background: "var(--panel)", border: "1px solid var(--border)", borderRadius: 8,
            boxShadow: "0 4px 16px rgba(0,0,0,.15)", minWidth: 180, maxHeight: 260, overflowY: "auto", padding: 6,
          }}
        >
          <div style={{ display: "flex", gap: 6, marginBottom: 6, fontSize: 11 }}>
            <button className="btn btn-ghost" style={{ fontSize: 11, padding: "2px 6px" }} onClick={() => onChange(new Set(options))}>Vybrať všetko</button>
            <button className="btn btn-ghost" style={{ fontSize: 11, padding: "2px 6px" }} onClick={() => onChange(new Set())}>Zrušiť všetko</button>
          </div>
          {options.map((o) => (
            <label key={o} style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, padding: "3px 4px", cursor: "pointer" }}>
              <input
                type="checkbox"
                checked={selected.has(o)}
                onChange={(e) => {
                  const next = new Set(selected);
                  if (e.target.checked) next.add(o); else next.delete(o);
                  onChange(next);
                }}
              />
              {o || "— bez hodnoty —"}
            </label>
          ))}
        </div>
      )}
    </span>
  );
}

function urcenieLabel(u) {
  if (!u || !u.typ) return "—";
  if (u.typ === "sklad") return "Na sklad";
  if (u.typ === "externa") return "Externá zákazka";
  if (u.typ === "stroj") return u.strojKod || "Stroj";
  return "—";
}

function copyColumn(rows, key, label) {
  const text = rows.map((r) => r[key] || "").join("\n");
  navigator.clipboard.writeText(text).then(
    () => {},
    () => alert(`Kopírovanie zlyhalo — skopíruj stĺpec "${label}" ručne.`)
  );
}

function exportSparePartsCSV(rows, filename) {
  const data = rows.map((p) => ({
    Depo: p.depo || "",
    Určenie: p.urcenie !== undefined ? urcenieLabel(p.urcenie) : "",
    Dodávateľ: p.dodavatel || "",
    "Číslo položky": p.cisloPolozky || "",
    "Počet kusov": p.pocetKusov || "",
    "Číslo dielu": p.cisloDielu || "",
    "Popis dielu": p.popisDielu || "",
    "Stav objednania": p.stav || "",
    "Dátum objednania": p.datumObjednania ? fmtDate(p.datumObjednania) : "",
    "Nákupná objednávka": p.nakupnaObjednavka || "",
    Poznámka: p.poznamka || "",
    "Zadal(a)": p.requestedBy || "",
  }));
  const csv = Papa.unparse(data);
  const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" }); // BOM, nech Excel nezobrazí diakritiku zle
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

function SparePartsView({ spareParts, machines, myEmployee, user, today, targetDepo, onTargetDepoConsumed, onAdd, onApprove, onReject, onRestore, onUpdate, onDelete, onImport }) {
  const canManage = can(user, "sparepart_manage");
  const myDepo = myEmployee?.depo || "";
  const depoOptions = DEPO_OPTIONS.filter((d) => d !== "Externé");
  const [activeDepo, setActiveDepo] = useState(canManage ? depoOptions[0] : myDepo);
  const [dodavatelFilter, setDodavatelFilter] = useState(null); // null = všetko zaškrtnuté (predvolené)
  const [periodMode, setPeriodMode] = useState("month"); // month | all | custom
  const [customStart, setCustomStart] = useState(today.slice(0, 8) + "01");
  const [customEnd, setCustomEnd] = useState(today);
  const [showAdd, setShowAdd] = useState(false);
  const [rejectingId, setRejectingId] = useState(null);
  const [confirmMessage, setConfirmMessage] = useState(null); // krátky zatvárateľný pás po odoslaní požiadavky
  const [searchQuery, setSearchQuery] = useState(""); // vyhľadávanie histórie naprieč všetkými depami a celým časom

  // Prišli sme sem kliknutím na notifikáciu o konkrétnom diele — prepneme
  // rovno na jeho depo, nech ho vedúci/dispečer nemusí ručne hľadať.
  useEffect(() => {
    if (targetDepo && canManage) {
      setActiveDepo(targetDepo);
      setDodavatelFilter(null);
      onTargetDepoConsumed?.();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [targetDepo]);

  const depo = canManage ? activeDepo : myDepo;
  const { start, end } = periodBounds(periodMode, today, customStart, customEnd);

  const depoRows = spareParts.filter((p) => p.depo === depo);
  // Filter obdobia sa týka LEN už objednaných položiek — nevybavené sa majú
  // vidieť vždy, nech sa nestratia z dohľadu len preto, že prešiel mesiac.
  const periodFiltered = periodMode === "all"
    ? depoRows
    : depoRows.filter((p) => p.stav !== SPAREPART_STAV.OBJEDNANE || !p.datumObjednania || (p.datumObjednania >= start && p.datumObjednania <= end));

  const dodavatelOptions = [...new Set(periodFiltered.map((p) => p.dodavatel || ""))].sort();
  const selectedDodavatelia = dodavatelFilter || new Set(dodavatelOptions);
  const rows = periodFiltered.filter((p) => selectedDodavatelia.has(p.dodavatel || ""));

  const pending = rows.filter((p) => p.stav === SPAREPART_STAV.CAKA_NA_SCHVALENIE);
  const zamietnute = rows.filter((p) => p.stav === SPAREPART_STAV.ZAMIETNUTE);
  // Objednané hore, zoradené podľa čísla nákupnej objednávky (od najmenšieho).
  const objednane = rows
    .filter((p) => p.stav === SPAREPART_STAV.OBJEDNANE)
    .sort((a, b) => (a.nakupnaObjednavka || "").localeCompare(b.nakupnaObjednavka || "", undefined, { numeric: true }));
  // Čaká na objednanie pod tým, zoradené podľa dodávateľa — nech sa dá kopírovať
  // dodávateľ po dodávateľovi bez miešania s už objednanými vecami.
  const cakaNaObjednanie = rows
    .filter((p) => p.stav === SPAREPART_STAV.CAKA_NA_OBJEDNANIE)
    .sort((a, b) => (a.dodavatel || "").localeCompare(b.dodavatel || ""));

  const columns = [
    { key: "dodavatel", label: "Dodávateľ" },
    { key: "cisloPolozky", label: "Číslo položky" },
    { key: "pocetKusov", label: "Počet kusov" },
    { key: "cisloDielu", label: "Číslo dielu" },
    { key: "popisDielu", label: "Popis dielu" },
    { key: "poznamka", label: "Poznámka" },
  ];

  // Vyhľadávanie histórie — naprieč VŠETKÝMI depami (u technika len jeho
  // vlastné) a CELÝM časom, nezávisle od filtra obdobia a aktívnej záložky.
  const searchScope = canManage ? spareParts : spareParts.filter((p) => p.depo === myDepo);
  const q = searchQuery.trim().toLowerCase();
  const searchResults = q
    ? searchScope
        .filter((p) => (p.cisloDielu || "").toLowerCase().includes(q) || (p.popisDielu || "").toLowerCase().includes(q))
        .sort((a, b) => (b.requestedAt || "").localeCompare(a.requestedAt || ""))
    : [];

  function renderGroupTable(groupRows, groupLabel, groupColor, showDodavatelFilter) {
    return (
      <div style={{ marginBottom: 20 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
          <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: groupColor }}>
            {groupLabel} ({groupRows.length})
          </div>
          {groupRows.length > 0 && (
            <button
              className="btn btn-ghost"
              style={{ fontSize: 10, padding: "2px 8px" }}
              onClick={() => exportSparePartsCSV(groupRows, `nahradne-diely-${depo}-${groupLabel.toLowerCase().replace(/\s+/g, "-")}.csv`)}
            >
              ⬇ Export do Excelu
            </button>
          )}
        </div>
        <div className="panel" style={{ padding: 0, overflow: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr>
                {columns.map((c) => (
                  <th key={c.key} style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)", whiteSpace: "nowrap" }}>
                    {c.label}
                    {c.key === "dodavatel" && showDodavatelFilter && (
                      <ColumnFilterButton label="Dodávateľ" options={dodavatelOptions} selected={selectedDodavatelia} onChange={setDodavatelFilter} />
                    )}
                    {" "}
                    <button className="btn btn-ghost" style={{ padding: "1px 5px", fontSize: 10 }} title={`Kopírovať stĺpec ${c.label}`} onClick={() => copyColumn(groupRows, c.key, c.label)}>⧉</button>
                  </th>
                ))}
                <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>
                  Určenie {" "}
                  <button className="btn btn-ghost" style={{ padding: "1px 5px", fontSize: 10 }} title="Kopírovať stĺpec Určenie" onClick={() => copyColumn(groupRows.map((p) => ({ urcenieText: urcenieLabel(p.urcenie) })), "urcenieText", "Určenie")}>⧉</button>
                </th>
                <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Stav objednania</th>
                <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Dátum objednania</th>
                <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>
                  Nákupná objednávka {" "}
                  <button className="btn btn-ghost" style={{ padding: "1px 5px", fontSize: 10 }} title="Kopírovať stĺpec Nákupná objednávka" onClick={() => copyColumn(groupRows, "nakupnaObjednavka", "Nákupná objednávka")}>⧉</button>
                </th>
                {canManage && <th></th>}
              </tr>
            </thead>
            <tbody>
              {groupRows.length === 0 ? (
                <tr><td colSpan={11} style={{ padding: 16, fontSize: 13, color: "var(--text-dim)" }}>Žiadne položky nezodpovedajú filtru.</td></tr>
              ) : (
                groupRows.map((p) => (
                  <tr key={p.id} style={{ borderTop: "1px solid var(--border)" }}>
                    {columns.map((c) =>
                      canManage ? (
                        <td key={c.key} style={{ padding: "4px 12px" }}>
                          <input
                            type={c.key === "pocetKusov" ? "number" : "text"}
                            value={p[c.key] || ""}
                            onChange={(e) => onUpdate(p.id, { [c.key]: e.target.value })}
                            style={{ fontSize: 13, width: c.key === "popisDielu" ? 160 : c.key === "pocetKusov" ? 60 : 100 }}
                          />
                        </td>
                      ) : (
                        <td key={c.key} style={{ padding: "6px 12px", fontSize: 13 }}>{p[c.key] || "—"}</td>
                      )
                    )}
                    <td style={{ padding: "6px 12px", fontSize: 13, whiteSpace: "nowrap" }}>{urcenieLabel(p.urcenie)}</td>
                    <td style={{ padding: "6px 12px" }}>
                      {canManage ? (
                        <select
                          value={p.stav}
                          onChange={(e) => {
                            const newStav = e.target.value;
                            onUpdate(p.id, newStav === SPAREPART_STAV.OBJEDNANE ? { stav: newStav, datumObjednania: today } : { stav: newStav });
                          }}
                          style={{
                            fontSize: 12, fontWeight: 600, border: "none", borderRadius: 5, padding: "3px 8px",
                            background: p.stav === SPAREPART_STAV.OBJEDNANE ? "var(--ok)" : "var(--warn)",
                            color: "#fff",
                          }}
                        >
                          <option value={SPAREPART_STAV.CAKA_NA_OBJEDNANIE}>Čaká na objednanie</option>
                          <option value={SPAREPART_STAV.OBJEDNANE}>Objednané</option>
                        </select>
                      ) : (
                        <span
                          style={{
                            fontSize: 12, fontWeight: 600, borderRadius: 5, padding: "3px 8px", color: "#fff",
                            background: p.stav === SPAREPART_STAV.OBJEDNANE ? "var(--ok)" : "var(--warn)",
                          }}
                        >
                          {p.stav}
                        </span>
                      )}
                    </td>
                    <td style={{ padding: "6px 12px" }}>
                      {canManage ? (
                        <input type="date" value={p.datumObjednania || ""} onChange={(e) => onUpdate(p.id, { datumObjednania: e.target.value })} style={{ fontSize: 12 }} />
                      ) : (
                        <span style={{ fontSize: 13 }}>{p.datumObjednania ? fmtDate(p.datumObjednania) : "—"}</span>
                      )}
                    </td>
                    <td style={{ padding: "6px 12px" }}>
                      {canManage ? (
                        <input value={p.nakupnaObjednavka || ""} onChange={(e) => onUpdate(p.id, { nakupnaObjednavka: e.target.value })} style={{ fontSize: 12, width: 110 }} />
                      ) : (
                        <span style={{ fontSize: 13 }}>{p.nakupnaObjednavka || "—"}</span>
                      )}
                    </td>
                    {canManage && (
                      <td style={{ padding: "6px 12px" }}>
                        <button className="btn btn-ghost" style={{ fontSize: 11, padding: "2px 6px", color: "var(--danger)" }} title="Vymazať riadok" onClick={() => onDelete(p.id)}>🗑</button>
                      </td>
                    )}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    );
  }

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 10, marginBottom: 14 }}>
        {canManage ? (
          <div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
            {depoOptions.map((d) => (
              <button
                key={d}
                className="btn"
                onClick={() => { setActiveDepo(d); setDodavatelFilter(null); }}
                style={{
                  fontSize: 12, padding: "5px 12px",
                  background: activeDepo === d ? "var(--accent)" : "transparent",
                  color: activeDepo === d ? "#fff" : "var(--text)",
                  border: "1px solid " + (activeDepo === d ? "var(--accent)" : "var(--border)"),
                }}
              >
                {d}
              </button>
            ))}
          </div>
        ) : (
          <div style={{ fontSize: 13, fontWeight: 600 }}>Depo: {myDepo || "— nemáte priradené depo —"}</div>
        )}
        <button className="btn btn-accent" onClick={() => setShowAdd(true)}>+ Nová požiadavka</button>
      </div>

      {confirmMessage && (
        <div
          style={{
            display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12,
            background: "var(--ok)", color: "#fff", padding: "10px 14px", borderRadius: 8, marginBottom: 16, fontSize: 13,
          }}
        >
          <span>✓ {confirmMessage}</span>
          <button className="btn btn-ghost" style={{ color: "#fff", padding: "2px 8px" }} onClick={() => setConfirmMessage(null)}>✕</button>
        </div>
      )}

      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16 }}>
        <input
          type="text"
          placeholder="Hľadať v histórii podľa čísla alebo popisu dielu (naprieč všetkými depami a celým časom)..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          style={{ flex: 1, maxWidth: 480 }}
        />
        {q && <button className="btn btn-ghost" onClick={() => setSearchQuery("")}>✕ Zrušiť hľadanie</button>}
      </div>

      {q ? (
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
            <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--text-dim)" }}>
              Výsledky hľadania ({searchResults.length})
            </div>
            {searchResults.length > 0 && (
              <button className="btn btn-ghost" style={{ fontSize: 10, padding: "2px 8px" }} onClick={() => exportSparePartsCSV(searchResults, `nahradne-diely-hladanie-${q}.csv`)}>
                ⬇ Export do Excelu
              </button>
            )}
          </div>
          <div className="panel" style={{ padding: 0, overflow: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Depo</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Určenie</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Stav</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Dátum objednania</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Nákupná objednávka</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Dodávateľ</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Počet kusov</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Číslo dielu</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Popis dielu</th>
                </tr>
              </thead>
              <tbody>
                {searchResults.length === 0 ? (
                  <tr><td colSpan={9} style={{ padding: 16, fontSize: 13, color: "var(--text-dim)" }}>Nič sa nenašlo.</td></tr>
                ) : (
                  searchResults.map((p) => (
                    <tr key={p.id} style={{ borderTop: "1px solid var(--border)" }}>
                      <td style={{ padding: "6px 12px", fontSize: 13 }}>{p.depo}</td>
                      <td style={{ padding: "6px 12px", fontSize: 13, whiteSpace: "nowrap" }}>{urcenieLabel(p.urcenie)}</td>
                      <td style={{ padding: "6px 12px" }}>
                        <span
                          style={{
                            fontSize: 12, fontWeight: 600, borderRadius: 5, padding: "3px 8px", color: "#fff",
                            background: p.stav === SPAREPART_STAV.OBJEDNANE ? "var(--ok)" : p.stav === SPAREPART_STAV.ZAMIETNUTE ? "var(--danger)" : "var(--warn)",
                          }}
                        >
                          {p.stav}
                        </span>
                      </td>
                      <td style={{ padding: "6px 12px", fontSize: 13 }}>{p.datumObjednania ? fmtDate(p.datumObjednania) : "—"}</td>
                      <td style={{ padding: "6px 12px", fontSize: 13 }}>{p.nakupnaObjednavka || "—"}</td>
                      <td style={{ padding: "6px 12px", fontSize: 13 }}>{p.dodavatel || "—"}</td>
                      <td style={{ padding: "6px 12px", fontSize: 13 }}>{p.pocetKusov || "—"}</td>
                      <td style={{ padding: "6px 12px", fontSize: 13 }}>{p.cisloDielu}</td>
                      <td style={{ padding: "6px 12px", fontSize: 13 }}>{p.popisDielu}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
      <>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16, flexWrap: "wrap" }}>
        {[["month", "Objednané: tento mesiac"], ["all", "Objednané: všetko"], ["custom", "Vlastný rozsah"]].map(([id, label]) => (
          <button
            key={id}
            className="btn"
            onClick={() => setPeriodMode(id)}
            style={{
              fontSize: 12, padding: "4px 10px",
              background: periodMode === id ? "var(--accent)" : "transparent",
              color: periodMode === id ? "#fff" : "var(--text-dim)",
              border: "1px solid " + (periodMode === id ? "var(--accent)" : "var(--border)"),
            }}
          >
            {label}
          </button>
        ))}
        {periodMode === "custom" && (
          <>
            <input type="date" value={customStart} onChange={(e) => setCustomStart(e.target.value)} />
            <span style={{ color: "var(--text-dim)" }}>—</span>
            <input type="date" value={customEnd} onChange={(e) => setCustomEnd(e.target.value)} />
          </>
        )}
      </div>

      {pending.length > 0 && canManage && (
        <div style={{ marginBottom: 20 }}>
          <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--warn)", marginBottom: 8 }}>
            Čaká na schválenie ({pending.length})
          </div>
          <div className="panel" style={{ padding: 0, overflow: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr>
                  {columns.map((c) => <th key={c.key} style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>{c.label}</th>)}
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Určenie</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {pending.map((p) => (
                  <tr key={p.id} style={{ borderTop: "1px solid var(--border)" }}>
                    {columns.map((c) => <td key={c.key} style={{ padding: "6px 12px", fontSize: 13 }}>{p[c.key] || "—"}</td>)}
                    <td style={{ padding: "6px 12px", fontSize: 13, whiteSpace: "nowrap" }}>{urcenieLabel(p.urcenie)}</td>
                    <td style={{ padding: "6px 12px", display: "flex", gap: 6 }}>
                      <button className="btn btn-accent" style={{ fontSize: 11, padding: "3px 8px" }} onClick={() => onApprove(p.id)}>Schváliť</button>
                      <button className="btn btn-ghost" style={{ fontSize: 11, padding: "3px 8px", color: "var(--danger)" }} onClick={() => setRejectingId(p.id)}>Zamietnuť</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {renderGroupTable(objednane, "Objednané", "var(--ok)", false)}
      {renderGroupTable(cakaNaObjednanie, "Čaká na objednanie", "var(--warn)", true)}
      {zamietnute.length > 0 && (
        <div style={{ marginBottom: 20 }}>
          <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--danger)", marginBottom: 8 }}>
            Zamietnuté ({zamietnute.length})
          </div>
          <div className="panel" style={{ padding: 0, overflow: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr>
                  {columns.map((c) => <th key={c.key} style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>{c.label}</th>)}
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Určenie</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Dôvod</th>
                  {canManage && <th></th>}
                </tr>
              </thead>
              <tbody>
                {zamietnute.map((p) => (
                  <tr key={p.id} style={{ borderTop: "1px solid var(--border)" }}>
                    {columns.map((c) => <td key={c.key} style={{ padding: "6px 12px", fontSize: 13 }}>{p[c.key] || "—"}</td>)}
                    <td style={{ padding: "6px 12px", fontSize: 13, whiteSpace: "nowrap" }}>{urcenieLabel(p.urcenie)}</td>
                    <td style={{ padding: "6px 12px", fontSize: 13, color: "var(--danger)" }}>{p.rejectionReason}</td>
                    {canManage && (
                      <td style={{ padding: "6px 12px", display: "flex", gap: 6 }}>
                        <button className="btn btn-ghost" style={{ fontSize: 11, padding: "2px 8px" }} onClick={() => onRestore(p.id)}>Obnoviť</button>
                        <button className="btn btn-ghost" style={{ fontSize: 11, padding: "2px 6px", color: "var(--danger)" }} title="Vymazať riadok" onClick={() => onDelete(p.id)}>🗑</button>
                      </td>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {canManage && (
        <div style={{ marginTop: 14 }}>
          <SparePartsImportButton depo={depo} onImport={onImport} />
        </div>
      )}
      </>
      )}

      {showAdd && (
        <AddSparePartModal
          canManage={canManage}
          defaultDepo={depo}
          machines={machines}
          onClose={() => setShowAdd(false)}
          onSave={(data) => {
            onAdd(data);
            setShowAdd(false);
            if (!canManage) {
              setConfirmMessage(
                data.length === 1
                  ? `Požiadavka odoslaná na schválenie: ${data[0].pocetKusov}× ${data[0].cisloDielu} — ${data[0].popisDielu}`
                  : `Požiadavka odoslaná na schválenie: ${data.length} položiek`
              );
            }
          }}
        />
      )}
      {rejectingId && (
        <RejectSparePartModal
          onClose={() => setRejectingId(null)}
          onConfirm={(reason) => { onReject(rejectingId, reason); setRejectingId(null); }}
        />
      )}
    </div>
  );
}

function SparePartsImportButton({ depo, onImport }) {
  const [show, setShow] = useState(false);
  const [rows, setRows] = useState([]);
  const [headers, setHeaders] = useState([]);
  const [mapDodavatel, setMapDodavatel] = useState("");
  const [mapCisloPolozky, setMapCisloPolozky] = useState("");
  const [mapPocetKusov, setMapPocetKusov] = useState("");
  const [mapCisloDielu, setMapCisloDielu] = useState("");
  const [mapPopisDielu, setMapPopisDielu] = useState("");
  const [mapStav, setMapStav] = useState("");
  const [mapDatum, setMapDatum] = useState("");
  const [mapObjednavka, setMapObjednavka] = useState("");
  const [mapPoznamka, setMapPoznamka] = useState("");

  function handleFile(e) {
    const file = e.target.files[0];
    if (!file) return;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (res) => {
        setHeaders(res.meta.fields || []);
        setRows(res.data);
      },
    });
  }

  function doImport() {
    const items = rows
      .map((r) => ({
        depo,
        dodavatel: mapDodavatel ? (r[mapDodavatel] || "").toString().trim() : "",
        cisloPolozky: mapCisloPolozky ? (r[mapCisloPolozky] || "").toString().trim() : "",
        pocetKusov: mapPocetKusov ? (r[mapPocetKusov] || "").toString().trim() : "",
        cisloDielu: mapCisloDielu ? (r[mapCisloDielu] || "").toString().trim() : "",
        popisDielu: mapPopisDielu ? (r[mapPopisDielu] || "").toString().trim() : "",
        stav: mapStav && (r[mapStav] || "").toString().trim() ? (r[mapStav] || "").toString().trim() : SPAREPART_STAV.OBJEDNANE,
        datumObjednania: mapDatum ? (r[mapDatum] || "").toString().trim() : "",
        nakupnaObjednavka: mapObjednavka ? (r[mapObjednavka] || "").toString().trim() : "",
        poznamka: mapPoznamka ? (r[mapPoznamka] || "").toString().trim() : "",
      }))
      .filter((x) => x.cisloDielu);
    onImport(items);
    setShow(false);
    setRows([]);
    setHeaders([]);
  }

  return (
    <>
      <button className="btn btn-ghost" onClick={() => setShow(true)}>Importovať históriu z Excelu (pre {depo})</button>
      {show && (
        <Modal title={`Import histórie náhradných dielov — ${depo}`} onClose={() => setShow(false)} wide>
          <Field label="Vyberte CSV súbor (exportovaný z Excelu, len pre toto depo)">
            <input type="file" accept=".csv" onChange={handleFile} />
          </Field>
          {headers.length > 0 && (
            <>
              <div className="resp-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10, marginBottom: 14 }}>
                {[
                  ["Dodávateľ", mapDodavatel, setMapDodavatel],
                  ["Číslo položky", mapCisloPolozky, setMapCisloPolozky],
                  ["Počet kusov", mapPocetKusov, setMapPocetKusov],
                  ["Číslo dielu", mapCisloDielu, setMapCisloDielu],
                  ["Popis dielu", mapPopisDielu, setMapPopisDielu],
                  ["Stav objednania", mapStav, setMapStav],
                  ["Dátum objednania", mapDatum, setMapDatum],
                  ["Nákupná objednávka", mapObjednavka, setMapObjednavka],
                  ["Poznámka", mapPoznamka, setMapPoznamka],
                ].map(([label, val, setter]) => (
                  <Field key={label} label={`Stĺpec = ${label}`}>
                    <select value={val} onChange={(e) => setter(e.target.value)} style={{ width: "100%" }}>
                      <option value="">—</option>
                      {headers.map((h) => <option key={h} value={h}>{h}</option>)}
                    </select>
                  </Field>
                ))}
              </div>
              <button className="btn btn-accent" disabled={!mapCisloDielu} onClick={doImport}>Importovať {rows.length} riadkov do {depo}</button>
            </>
          )}
        </Modal>
      )}
    </>
  );
}

function DepoCheckerSettingsView({ depoCheckers, technicians, checkerSubstitutions, onDeleteSubstitution, onSave }) {
  const [values, setValues] = useState(depoCheckers || {});
  const technicianName = (id) => technicians.find((t) => t.id === id)?.name || "—";

  return (
    <div>
      <div style={{ fontSize: 13, color: "var(--text-dim)", marginBottom: 16 }}>
        Kto skontroluje/pripraví stroj na danom depe pri vývoze aj zvoze — platforma to už nebude pýtať pri
        každej zákazke zvlášť. Zmeňte tu kedykoľvek (dovolenka, zmena osoby na tejto úlohe a pod.) —
        pri zadaní dovolenky checkerovi priamo v Pláne servisu platforma navyše sama ponúkne dočasnú náhradu.
      </div>
      <div style={{ maxWidth: 420 }}>
        {DEPO_OPTIONS.map((depo) => (
          <Field key={depo} label={depo}>
            <select
              value={values[depo] || ""}
              onChange={(e) => setValues((v) => ({ ...v, [depo]: e.target.value || undefined }))}
              style={{ width: "100%" }}
            >
              <option value="">— nenastavené —</option>
              {technicians.filter((t) => !t.archived).map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>
          </Field>
        ))}
        <button
          className="btn btn-accent"
          style={{ marginBottom: 20 }}
          onClick={() => {
            // vyčistí prázdne hodnoty, nech sa v databáze nehromadí "undefined"
            const cleaned = {};
            Object.entries(values).forEach(([k, v]) => {
              if (v) cleaned[k] = v;
            });
            onSave(cleaned);
          }}
        >
          Uložiť
        </button>
      </div>
      {checkerSubstitutions && checkerSubstitutions.length > 0 && (
        <>
          <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--text-dim)", marginBottom: 8 }}>
            Aktívne/naplánované náhrady (dovolenka)
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 6, maxWidth: 560 }}>
            {checkerSubstitutions.map((s) => (
              <div key={s.id} className="panel" style={{ padding: 10, display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", fontSize: 12 }}>
                <span><strong>{s.depo}</strong>: {technicianName(s.originalTechnicianId)} → {technicianName(s.substituteTechnicianId)}</span>
                <span style={{ color: "var(--text-dim)" }}>({fmtDate(s.startDate)} – {fmtDate(s.endDate)})</span>
                <button
                  className="btn btn-ghost"
                  style={{ fontSize: 11, padding: "3px 7px", color: "var(--danger)", marginLeft: "auto" }}
                  onClick={() => onDeleteSubstitution(s.id)}
                >
                  Zmazať
                </button>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

function UserAdminModal({ profiles, currentUser, onClose, onUpdate, onDelete, onResetPassword }) {
  const [editingId, setEditingId] = useState(null);

  return (
    <Modal title="Správa používateľov" onClose={onClose} wide>
      <div style={{ fontSize: 13, color: "var(--text-dim)", marginBottom: 14 }}>
        Noví ľudia sa registrujú sami na prihlasovacej obrazovke — tu im len prideľte rolu, prípadne ich deaktivujte/zmažte.
      </div>
      <table>
        <thead>
          <tr>
            <th>Meno</th>
            <th>Email</th>
            <th>Rola</th>
            <th>Stav</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {profiles.length === 0 && (
            <tr><td colSpan={5} style={{ textAlign: "center", padding: 30, color: "var(--text-dim)" }}>Zatiaľ žiadni používatelia.</td></tr>
          )}
          {profiles.map((p) => (
            <tr key={p.id}>
              <td style={{ fontWeight: 600 }}>{p.name}{p.id === currentUser?.id ? " (vy)" : ""}</td>
              <td className="mono">{p.email || (p.id === currentUser?.id ? currentUser.email : "—")}</td>
              <td>
                {p.id === currentUser?.id ? (
                  <span
                    style={{ color: "var(--text-dim)" }}
                    title="Svoju vlastnú rolu si nemôžete zmeniť — musí ju zmeniť iný administrátor (poistka, aby platforma neostala bez admina)"
                  >
                    {roleLabel(p.role)}
                  </span>
                ) : editingId === p.id ? (
                  <select
                    autoFocus
                    defaultValue={p.role}
                    onChange={(e) => { onUpdate(p.id, { role: e.target.value }); setEditingId(null); }}
                    onBlur={() => setEditingId(null)}
                  >
                    {ROLES.map((r) => <option key={r.id} value={r.id}>{r.label}</option>)}
                  </select>
                ) : (
                  <span style={{ cursor: "pointer", textDecoration: "underline" }} onClick={() => setEditingId(p.id)}>
                    {roleLabel(p.role)}
                  </span>
                )}
              </td>
              <td>{p.active === false ? <span className="badge badge-danger">Deaktivovaný</span> : <span className="badge badge-ok">Aktívny</span>}</td>
              <td style={{ display: "flex", gap: 6, justifyContent: "flex-end", flexWrap: "wrap" }}>
                {(p.email || p.id === currentUser?.id) && (
                  <button
                    className="btn btn-ghost"
                    style={{ fontSize: 11, padding: "4px 8px" }}
                    onClick={() => onResetPassword(p.email || currentUser.email)}
                    title="Pošle používateľovi mail s odkazom na nastavenie nového hesla"
                  >
                    Resetovať heslo
                  </button>
                )}
                {p.id !== currentUser?.id && (
                  <button
                    className="btn btn-ghost"
                    style={{ fontSize: 11, padding: "4px 8px" }}
                    onClick={() => onUpdate(p.id, { active: p.active === false ? true : false })}
                  >
                    {p.active === false ? "Aktivovať" : "Deaktivovať"}
                  </button>
                )}
                {p.id !== currentUser?.id && (
                  <button className="btn btn-ghost" style={{ fontSize: 11, padding: "4px 8px", color: "var(--danger)" }} onClick={() => onDelete(p.id)}>
                    Zmazať
                  </button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </Modal>
  );
}

